CREATE TABLE IF NOT EXISTS employees (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, number TEXT NOT NULL UNIQUE, allowance INTEGER NOT NULL DEFAULT 0, day_off INTEGER NOT NULL DEFAULT -1);
CREATE TABLE IF NOT EXISTS requests (id INTEGER PRIMARY KEY AUTOINCREMENT, employee_id INTEGER NOT NULL REFERENCES employees(id), date TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'pending', reviewed_at TEXT, reviewed_by TEXT, review_note TEXT, UNIQUE(employee_id,date));
CREATE INDEX IF NOT EXISTS idx_requests_date ON requests(date);
CREATE TABLE IF NOT EXISTS periods (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'Overig');
CREATE TABLE IF NOT EXISTS day_limits (
  date TEXT NOT NULL PRIMARY KEY,
  day_limit INTEGER NOT NULL CHECK (typeof(day_limit) = 'integer' AND day_limit BETWEEN 0 AND 9007199254740991)
);
